hat no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987252011,"bound_title":"De nachtegaal","reviewed_at":"2026-11-03T11:21:20.152+00:00","bound_isbn13":"9789049205430","evidence_url":"https://data.bibliotheken.nl/id/nbt/p442975430","review_batch":"nl-scale-20261102-053","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":928300586}'::jsonb as exact union all select 'editions:6' as ref,(select to_jsonb(t) from public.editions t where t.id=987252008)='{"id":987252008,"title":"De Blinde Horlogemaker","isbn_10":"9025467415","isbn_13":"9789025467418","work_id":987152005,"cover_id":null,"language":"dut","publisher":"Contact","publish_date":null,"open_library_edition_id":"OL25696571M"}'::jsonb as exact union all select 'catalog_work_descriptions:7' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987152005 and t.language='nl')='{"text":"Richard Dawkins onderzoekt hoe de ingewikkelde vormen van levende wezens kunnen ontstaan zonder dat een ontwerper het resultaat vooraf heeft bedacht. Tegenover het beeld van een doelgerichte natuur plaatst hij Darwins natuurlijke selectie. Hij gebruikt onder meer computersimulaties om te laten zien hoe opeenvolgende kleine veranderingen grotere verschillen kunnen opleveren. Het boek verbindt deze voorbeelden met vragen over genen en aanpassing. Zo licht Dawkins toe waarom een complex organisme volgens hem niet om een vooraf opgesteld plan vraagt.","work_id":987152005,"evidence":[{"note":"Retain existing Work2401 The Blind Watchmaker / Richard Dawkins; exact Dutch De Blinde Horlogemaker ISBN 9789025467418 Paperback. Bibliography explicitly binds Dutch language, author, original title and source parent. Original content review content-review-021.json re-read, including Dawkins contrasts natural selection with Paley''s purposeful design; Computer simulations illustrate cumulative evolutionary change. No new Work, author merge, additional Dut